INSERT INTO param_version (version, created_at, observed_cnt, public_cnt, assumed_cnt, total_cnt, payload) VALUES
('1.0', '2026-11-04 00:00:00', 10, 1, 19, 31, '[{"id": "P-DAILY-ARRIVAL", "group": "A 体量", "label": "设计峰值日到件量（四站合计）", "value": 13640, "unit": "件/日", "range": [11000, 16000], "source": "assumed", "source_ids": ["S03", "STAT-001"], "rationale": "学校公开报道“日均 >12000 件”为全校口径；四站分摊后取 13640 作为双11场景的设计峰值。", "used_by": ["scenarios.json S2/S3"], "swap_hint": "拿到驿站真实日均后替换，并重跑 calibrate_norm"}, {"id": "P-D11-MULT", "group": "A 体量", "label": "旺季相对日常的放大倍数", "value": 2.2, "unit": "倍", "range": [1.18, 3], "source": "assumed", "source_ids": ["S19", "S21"], "rationale": "下界 1.18 来自国家邮政局“双11日均=日常117.8%”；上界 3.0 来自高校开学季“比平时增加约2倍”。校园电商渗透高、取件集中，取中上值 2.2。", "used_by": ["scenarios.json"], "swap_hint": "替换后需重算 S2/S3 全部逐桶数据"}, {"id": "P-CARRIER-SHARE", "group": "A 体量", "label": "承运商件量份额", "value": {"顺丰": 0.12, "京东": 0.1, "中通": 0.18, "圆通": 0.15, "韵达": 0.14, "申通": 0.11, "邮政EMS": 0.08, "其他": 0.12}, "unit": "占比", "range": [0.6, 1.6], "source": "assumed", "source_ids": ["S01"], "rationale": "按行业内常见份额排序构造；顺丰/京东份额偏高，因为两者在主站有独立服务区（公开资料支持）。区间为整体缩放。", "used_by": ["实体仿真 批次生成"], "swap_hint": "可由驿站公示的“各家货架数”近似反推"}, {"id": "P-PICKUP-RATIO", "group": "A 体量", "label": "当日取件量 / 当日到件量", "value": 0.68, "unit": "比例", "range": [0.55, 0.8], "source": "assumed", "source_ids": ["S21"], "rationale": "保管期 3 天、学生当天取件为主；0.68 与“日均积压 ≈ 32% 结转到次日”自洽，且与 S1/S2 场景的 9300/13640 一致。", "used_by": ["scenarios.json"], "swap_hint": "用真实出入库流水替换"}, {"id": "P-STUDENT-POP", "group": "A 体量", "label": "南湖校区在校生规模", "value": 20000, "unit": "人", "range": [15000, 25000], "source": "assumed", "source_ids": ["S02"], "rationale": "仅用于把“件量”换算成“人均件量”做合理性检查（13640/20000 ≈ 0.68 件/人/日，落在合理区间）。", "used_by": ["合理性检查"], "swap_hint": "用学校官网公开的在校生数替换"}, {"id": "P-BATCH-WINDOWS", "group": "B 作业", "label": "到车时间窗口", "value": ["08:30", "12:30", "16:00"], "unit": "时刻", "range": [-45, 45], "source": "assumed", "source_ids": ["S19", "S21"], "rationale": "按“凌晨分拨、早班进城、午间补车、傍晚二次补车”的普遍节奏构造三个窗口；区间为前后 45 分钟的三角分布抖动。", "used_by": ["实体仿真 批次生成"], "swap_hint": "现场蹲点记录即可替换（本项属可观测字段）"}, {"id": "P-TRUCK-LOAD", "group": "B 作业", "label": "单车装载量", "value": [800, 1200, 1800], "unit": "件/车", "range": [600, 2000], "source": "assumed", "source_ids": [], "rationale": "按常见厢式货车容积与包裹平均体积反推；大站一次到车 1000—2000 件是行业常见量级。", "used_by": ["实体仿真 批次生成"], "swap_hint": "数一次到车件数即可替换"}, {"id": "P-UNLOAD-RATE", "group": "B 作业", "label": "卸货+初分速度", "value": 25, "unit": "件/分钟/人", "range": [20, 30], "source": "assumed", "source_ids": ["S21"], "rationale": "按人工卸车并粗分道的常见节拍；区间取自公开作业规范的常见范围。", "used_by": ["实体仿真 卸货"], "swap_hint": "现场掐表即可替换"}, {"id": "P-STAFF", "group": "B 作业", "label": "在岗人数", "value": {"NH-TAOYUAN": 6, "NH-SONGYUAN": 0, "NH-MEIYUAN": 0, "NH-LANYUAN": 0}, "unit": "人", "range": [4, 8], "source": "assumed", "source_ids": ["S21"], "rationale": "主站有 1 个服务台 + 分拣；三个无人站为自助扫码，无常驻人员。开学季某校驿站 30 人只用于说明峰值人力可扩张。", "used_by": ["实体仿真 卸货/服务台"], "swap_hint": "观察一次即可替换"}, {"id": "P-HOLD-DAYS", "group": "B 作业", "label": "包裹保管期", "value": 3, "unit": "天", "range": [3, 10], "source": "assumed", "source_ids": ["S24"], "rationale": "制度上“无法投递应退回”，天数由站点自定；驿站普遍 3 天短信提醒、超期退回，也有站点放宽到 7—10 天。取 3 天。", "used_by": ["实体仿真 超时退回"], "swap_hint": "看驿站告示即可替换"}, {"id": "P-TIERS", "group": "C 储位", "label": "货架层数（含顶层）", "value": 5, "unit": "层", "range": [3, 5], "source": "observed", "source_ids": ["S25"], "rationale": "桃苑与兰苑实景照片均可见 5 层（红梁标签 505-1…505-5），全站统一 5 层", "used_by": ["平面图模板", "储位分配"], "swap_hint": "以正面照片确认", "evidence": "reference/taoyuan_photo_evidence.json#tiers"}, {"id": "P-SLOTS-PER-TIER", "group": "C 储位", "label": "每层储位数", "value": 20, "unit": "个", "range": [18, 24], "source": "observed", "source_ids": ["S25"], "rationale": "用户 2026-11-03 更正：单层装满时可达 20 件以上。按 1.5 m 开间 ÷ 约 7.5 cm 一件（含间隙）≈ 20。", "used_by": ["平面图模板", "储位分配"], "swap_hint": "以正面照片逐层清点", "evidence": "reference/taoyuan_photo_evidence.json#derived_layout"}, {"id": "P-SLOT-CAPACITY", "group": "C 储位", "label": "单储位容量", "value": 1, "unit": "件", "range": [1, 2], "source": "observed", "source_ids": ["S25"], "rationale": "照片中每个位置放一件并贴 4 位序号标签，便于按码定位；小件偶有前后相邻两件。", "used_by": ["储位分配"], "swap_hint": "—", "evidence": "reference/taoyuan_photo_evidence.json#parcel_label"}, {"id": "P-CODE-FORMAT", "group": "C 储位", "label": "取件码结构", "value": "货架号(3位)-层号(1位)-序号(4位)", "unit": "格式", "range": null, "source": "observed", "source_ids": ["S25", "S20"], "rationale": "四张实景照片的每块货架号牌底部都印着“取件码规则”示例（108-3-2441、147-3-2441、41-1），格式统一为 货架号-层号-序号；S20 的公开报道只说到“前两位对货架与层”，本项以照片为准。", "used_by": ["取件码生成"], "swap_hint": "以驿站实际短信为准", "evidence": "reference/taoyuan_photo_evidence.json#pickup_code_format"}, {"id": "P-SERVICE-TIME", "group": "D 服务", "label": "单人取件服务时长", "value": {"counter_sec": 90, "self_sec": 25}, "unit": "秒/人", "range": [0.7, 1.4], "source": "assumed", "source_ids": ["S20"], "rationale": "人工台：报码—找件—扫码—交付约 90 秒；自助：按码找件—扫码约 25 秒（不含找件时间）。区间为整体缩放。", "used_by": ["实体仿真 排队"], "swap_hint": "现场计时即可替换"}, {"id": "P-PICKUP-CURVE", "group": "D 服务", "label": "取件时段分布", "value": [0.02, 0.05, 0.1, 0.13, 0.1, 0.08, 0.07, 0.08, 0.12, 0.14, 0.07, 0.04], "unit": "占日取件比例（08:00 起每 1.5 小时一格）", "range": [0.6, 1.4], "source": "assumed", "source_ids": ["S21"], "rationale": "课间与晚饭后两个峰（12:00 与 18:00 前后），上午偏低；区间为整体缩放。", "used_by": ["实体仿真 取件"], "swap_hint": "用驿站出库流水替换"}, {"id": "P-PICKUP-DELAY", "group": "D 服务", "label": "取件延迟分布", "value": {"same_day": 0.6, "next_day": 0.3, "overdue": 0.1}, "unit": "比例", "range": [0.5, 0.7], "source": "assumed", "source_ids": ["S24"], "rationale": "当天取为主，次日次之；超过保管期进“超时退回”流程。", "used_by": ["实体仿真 取件"], "swap_hint": "用真实取件时间戳替换"}, {"id": "P-VEHICLE-SPEED", "group": "E 运输", "label": "校内配送平均速度", "value": 15, "unit": "km/h", "range": [10, 20], "source": "assumed", "source_ids": [], "rationale": "电动三轮车新国标限速 25 km/h，校内需避让学生、过减速带，平均取 15 km/h。", "used_by": ["实体仿真 路径时间"], "swap_hint": "实测一次到车行驶时间即可替换"}, {"id": "P-VEHICLE-LOAD", "group": "E 运输", "label": "配送车单次载量", "value": {"kg": 300, "parcels": 120}, "unit": "kg / 件", "range": [0.7, 1.3], "source": "assumed", "source_ids": [], "rationale": "三轮车常见载重 300 kg；按平均 2.5 kg/件折算约 120 件。", "used_by": ["实体仿真 转运"], "swap_hint": "—"}, {"id": "P-ROUTE-GRAPH", "group": "E 运输", "label": "院内路网图规模", "value": {"nodes": 615, "edges": 647}, "unit": "个", "range": null, "source": "observed", "source_ids": ["S02"], "rationale": "由本项目从 OSM 道路中心线构建并实测（probe_route_graph.py）。四站里程 829/948/1775/— m。", "used_by": ["实体仿真 路径"], "swap_hint": "换成学校官方路网或实测轨迹"}, {"id": "P-LANYUAN-LINK", "group": "E 运输", "label": "兰苑连接段（补绘）", "value": 60, "unit": "m", "range": [40, 120], "source": "assumed", "source_ids": [], "rationale": "现有 OSM 路网中兰苑不与主网连通，补一条约 60 m 的连接段；数据里标注“补绘”，不是实测。", "used_by": ["实体仿真 路径"], "swap_hint": "用真实路网替换后删除本参数"}, {"id": "P-RACK-COUNT", "group": "C 储位", "label": "主站货架总数", "value": 240, "unit": "架", "range": [240, 300], "source": "observed", "source_ids": ["S25"], "evidence": "reference/taoyuan_photo_evidence.json#rack_numbering；用户 2026-11-03 口头更正：至少 220 架", "rationale": "用户要求“最右列补齐到与另外两列等长”，即三列等长货架：3 列 × 8 排 × 每排 10 个货架号 = 240 个（与“至少 220”一致）。", "used_by": ["平面图模板", "储位分配", "容量换算"], "swap_hint": "以全景或平面图确认后替换"}, {"id": "P-AISLE-WIDTH", "group": "C 储位", "label": "货架间通道宽度", "value": 0.8, "unit": "m", "range": [0.75, 0.9], "source": "observed", "source_ids": ["S25"], "evidence": "reference/taoyuan_photo_evidence.json#aisle", "rationale": "用户 2026-11-03 更正：通道约 80 cm，不是 1.3 m。照片里两人错身需侧身、手推车无法双向通过，与 0.8 m 一致。这个宽度直接决定了“货架占用率一高，通道就堵”。", "used_by": ["平面图模板"], "swap_hint": "以实测替换"}, {"id": "P-PHYSICAL-SLOTS", "group": "C 储位", "label": "物理储位总数（推算）", "value": 24000, "unit": "个", "range": [19200, 36000], "source": "observed", "source_ids": ["S25"], "evidence": "reference/taoyuan_photo_evidence.json#derived_layout", "rationale": "240 架 × 5 层 × 20 位 = 24,000（桃苑）", "used_by": ["容量换算"], "swap_hint": "以实测替换"}, {"id": "P-KAPPA-I-SHARE", "group": "C 储位", "label": "待取上限 κ_i 占物理储位的比例", "value": 0.22, "unit": "比例", "range": [0.12, 0.35], "source": "assumed", "source_ids": ["S25"], "evidence": null, "rationale": "κ_i（桃苑 2372）÷ 物理储位 10560 = 22.5%。这个比值远低于 1，说明瓶颈不在货架容量，而在通道作业面与人力——照片里通道只有 1.3 m、取件靠人走进去拿，包裹一多就堵通道。因此 κ_i 是运营管理阈值，不是物理容量。", "used_by": ["宏观层与实体层对齐"], "swap_hint": "拿到真实在架件数与货架数后重算"}, {"id": "P-SHELF-OBSERVED", "group": "C 储位", "label": "货架构造（照片实测）", "value": {"length_mm": 1500, "depth_mm": 600, "height_mm": 2000, "type": "重型金属货架，红横梁+灰立柱+白层板"}, "unit": "mm", "range": [0.85, 1.15], "source": "observed", "source_ids": ["S25", "S23"], "rationale": "照片中为典型仓储货架：红横梁、灰立柱、白层板；高度与人的比例约 2 m，深度按标准 0.6 m；长度按号牌跨度与通道内可见货架段估 1.5 m。", "used_by": ["平面图模板", "储位分配"], "swap_hint": "以实测尺寸替换", "evidence": "reference/taoyuan_photo_evidence.json#shelf_construction"}, {"id": "P-SHELF-SPEC", "group": "C 储位", "label": "驿站货架公开商品规格", "value": {"length_mm": 1800, "depth_mm": 600, "height_mm": 2000, "tiers": 5}, "unit": "mm", "range": [0.9, 1.1], "source": "public", "source_ids": ["S23"], "evidence": null, "rationale": "电商平台上“快递驿站专用货架”的主流规格，多家厂商一致；作为同量级参照物，用来校验照片估算（1.5 m 长、2 m 高、4 层）没有离谱。", "used_by": ["平面图模板（校验）"], "swap_hint": "—"}, {"id": "P-RACK-COUNT-LANYUAN", "label": "兰苑货架总数", "value": 55, "unit": "架", "source": "observed", "range": [55, 55], "rationale": "实景照片 491—545 共 55 个货架号", "value_kind": "count"}, {"id": "P-RACK-COUNT-SONGYUAN", "label": "松苑货架总数", "value": 79, "unit": "架", "source": "assumed", "range": [55, 95], "rationale": "用户口径：松苑货架不比兰苑少。按到件份额同比推算 55 × 26/18 ≈ 79 架（兰苑 55 架为实测基准）", "value_kind": "count"}, {"id": "P-RACK-COUNT-MEIYUAN", "label": "梅苑货架总数", "value": 67, "unit": "架", "source": "assumed", "range": [55, 85], "rationale": "用户口径：梅苑货架不比兰苑少。按到件份额同比推算 55 × 22/18 ≈ 67 架（兰苑 55 架为实测基准）", "value_kind": "count"}, {"id": "P-PHYSICAL-SLOTS-BY-SITE", "label": "各站物理储位", "value": {"NH-TAOYUAN": 24000, "NH-SONGYUAN": 7900, "NH-MEIYUAN": 6700, "NH-LANYUAN": 5500}, "unit": "个", "source": "observed+assumed", "value_kind": "map", "rationale": "货架数 × 5 层 × 20 位；桃苑与兰苑为实测货架数，松苑/梅苑为假设"}]');
